            for j in range(len(outputs[i]), len(inputs[i])):
                print(f"  Extra char in input at pos {j}: '{inputs[i][j]}'")
        elif len(outputs[i]) > len(inputs[i]):
            for j in range(len(inputs[i]), len(outputs[i])):
                print(f"  Extra char in output at pos {j}: '{outputs[i][j]}'")

